const { hashSync } = require('@exodus/crypto/hash')
const blake2b256 = require('./blake2b256')

function sha256 (buffer) {
  return hashSync('sha256', buffer, 'buffer')
}

function hash160 (buffer) {
  return hashSync('hash160', buffer, 'buffer')
}

function hash256 (buffer) {
  return sha256(sha256(buffer))
}

module.exports = {
  hash160: hash160,
  hash256: hash256,
  sha256: sha256,
  blake2b256: blake2b256
}
